src/index.css:
@import "tailwindcss";
@theme inline {
 --color-background: var(--background); --color-foreground: var(--foreground);
 --color-card: var(--card); --color-card-foreground: var(--foreground);
 --color-popover: var(--card); --color-popover-foreground: var(--foreground);
 --color-primary: var(--primary); --color-primary-foreground: var(--primary-foreground);
 --color-secondary: var(--secondary); --color-secondary-foreground: var(--foreground);
 --color-muted: var(--secondary); --color-muted-foreground: var(--muted-foreground);
 --color-accent: var(--secondary); --color-accent-foreground: var(--foreground);
 --color-destructive: #ef7777; --color-border: var(--border); --color-input: var(--border); --color-ring: var(--primary);
 --radius-sm: 6px; --radius-md: 10px; --radius-lg: 16px; --radius-xl: 22px;
}
:root {color-scheme:dark;--background:#111216;--foreground:#f2f3f5;--card:#1b1d23;--primary:#b7ceff;--primary-foreground:#172237;--secondary:#272a33;--muted-foreground:#a4a9b6;--border:#343841;font-family:ui-sans-serif,system-ui,sans-serif}
* {box-sizing:border-box;border-color:var(--border)}
body {margin:0;background:var(--background);color:var(--foreground);min-width:320px}
button,a {transition:background-color .18s,color .18s,box-shadow .18s,transform .18s}
button:focus-visible,a:focus-visible {outline:2px solid var(--primary);outline-offset:4px}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}

